using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
 bool Bad(Renderer r){var mf=r.GetComponent<MeshFilter>();var mesh=mf?mf.sharedMesh:(r is SkinnedMeshRenderer sk?sk.sharedMesh:null);string s=(AssetDatabase.GetAssetPath(mesh)+"|"+r.name+"|"+r.transform.parent?.name).ToLowerInvariant();return s.Contains("searsia_lucida")||s.Contains("pine_00")||s.Contains("pine_d")||s.Contains("pine_c")||s.Contains("pine_b");}
 public void Execute(ExecutionResult result){var s=EditorSceneManager.OpenScene("Assets/Scenes/Enroth_Linked_OpenWorld.unity",OpenSceneMode.Single);var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&Bad(r)).ToArray();var rows=rs.GroupBy(r=>{var mf=r.GetComponent<MeshFilter>();var mesh=mf?mf.sharedMesh:(r is SkinnedMeshRenderer sk?sk.sharedMesh:null);return AssetDatabase.GetAssetPath(mesh)+"|"+r.name+"|"+r.transform.parent?.name;}).OrderByDescending(g=>g.Count()).Select(g=>g.Count()+"|"+g.Key).ToArray();Directory.CreateDirectory("Validation/FinalWorld");File.WriteAllLines("Validation/FinalWorld/bad_visible_groups.txt",rows);result.Log("bad groups="+rows.Length+" renderers="+rs.Length);}}